import React from "react";
import { graphql, Link } from "gatsby";
import Layout from "../components/Layout"
import BreadCrumb from "../components/BreadCrumb"
import ProductCard from "../components/product-card";


export function Head(){
	return (
		<title>Shop</title>
	);
}







export default function Shop({ data }) {
  const products = data.allMerchantProduct.nodes;


  return (
	  <Layout>
      	<BreadCrumb links={[ "/"]} titles={["Home","Products"]} />
<div className="product-grid">
  {products.map(p => (
    <ProductCard
      key={p.id}
      title={p.title}
      price={ p.price }
      currency={ p.currency }
      description={p.description}
      image={p.imageUrl}
      merchant={p.brand || "Store"}
      url={`/products/${p.slug}`}
      badge={p.salePrice ? "Sale" : null}
      originalPrice={
        p.salePrice ? `${p.price} ${p.currency}` : null
      }
      price={
        p.salePrice
          ? `${p.salePrice} ${p.currency}`
          : `${p.price} ${p.currency}`
      }
    />
  ))}
    </div></Layout>
  );
}

export const query = graphql`
  {
    allMerchantProduct(sort: { fields: title }) {
      nodes {
        id
        title
        slug
        price
        currency
        imageUrl
	description
	}
    }
  }
`;

